list_discount_profiles.code:
final response = await client.discountProfiles
    .listDiscountProfiles(queryParams: {'sort': 'name', 'dir': 'asc'});
final profiles = (response.map as Map)['discount_profiles'] as List;
for (final profile in profiles) {
  print('${(profile as Map)['id']} ${profile['name']} ${profile['type']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

get_discount_profile.code:
final response = await client.discountProfiles.getDiscountProfile(1001);
final profile = (response.map as Map)['discount_profile'] as Map;
print('${profile['name']} ${profile['type']} ${profile['is_active']}');
for (final coupon in profile['customer_coupons'] as List) {
  print('${(coupon as Map)['code']} ${coupon['customer_email']}');
}

